interface User { id: number; name: string; email?: string }

type UserPatch = Partial<User>;      // all optional
function updateUser(id: number, patch: UserPatch) {}
updateUser(1, { name: 'New' });       // ✅ subset ok

type StrictUser = Required<User>;     // email now required
// Under the hood:
type MyPartial<T> = { [K in keyof T]?: T[K] };

interface Article {
  id: string;
  title: string;
  body: string;
  authorIp: string;
}

type ArticleCard = Pick<Article, 'id' | 'title'>;
type PublicArticle = Omit<Article, 'authorIp'>;

type ViewsByStatus = Record<'draft' | 'published', number>;
const views: ViewsByStatus = { draft: 3, published: 12 };

function createSession(userId: string, ttlDays = 7) {
  return { token: crypto.randomUUID(), expiresAt: Date.now() + ttlDays * 864e5 };
}

type Session = ReturnType<typeof createSession>;
type SessionArgs = Parameters<typeof createSession>; // [userId: string, ttlDays?: number]

function timed<A extends unknown[], R>(fn: (...args: A) => R): (...args: A) => R {
  return (...args) => {
    console.time('call');
    try { return fn(...args); } finally { console.timeEnd('call'); }
  };
}

interface ApiError { status: number; message: string }

function isApiError(e: unknown): e is ApiError {
  return typeof e === 'object' && e !== null
    && 'status' in e && 'message' in e;
}

try { await api.call(); }
catch (err: unknown) {
  if (isApiError(err)) showToast(err.message); // err: ApiError here
  else throw err;
}

function assertDefined<T>(v: T | undefined): asserts v is T {
  if (v === undefined) throw new Error('Missing value');
}

// NonNullable's implementation:
type MyNonNullable<T> = T extends null | undefined ? never : T;
type Clean = MyNonNullable<string | null | undefined>; // string

// Recursion example:
type DeepReadonly<T> = T extends (infer U)[]
  ? readonly DeepReadonly<U>[]
  : T extends object
    ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
    : T;

type ThemeConfig = Record<string, { dark: boolean; accent: string }>;

const themes = {
  sunset: { dark: true, accent: '#ff7a59' },
  ocean:  { dark: false, accent: '#2563eb' },
} satisfies ThemeConfig;

themes.sunset.accent; // type stays '#ff7a59' (literal!) — not string
